public record Sample(String zone, int number, int ppm) {
    public Sample {
        if (zone == null || !zone.matches("[A-Z]{1,6}") || number < 1 || number > 1000 || ppm < 0 || ppm > 5000) throw new IllegalArgumentException("Invalid sample");
    }
}

import java.io.IOException;
public final class SampleFormatException extends IOException {
    private static final long serialVersionUID = 1L;
    private final int lineNumber;
    public SampleFormatException(int lineNumber) { super("Invalid sample at line " + lineNumber); this.lineNumber = lineNumber; }
    public int lineNumber() { return lineNumber; }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class AirAudit {
    private AirAudit() {}
    private static int canonicalInt(String text) {
        int value = Integer.parseInt(text);
        if (!Integer.toString(value).equals(text)) throw new IllegalArgumentException("Invalid integer");
        return value;
    }
    public static List<Sample> parse(Reader reader) throws IOException {
        BufferedReader buffered = reader instanceof BufferedReader ? (BufferedReader) reader : new BufferedReader(reader);
        List<Sample> samples = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        String line;
        int number = 0;
        while ((line = buffered.readLine()) != null) {
            number++;
            String[] fields = line.split(java.util.regex.Pattern.quote("^"), -1);
            try {
                if (fields.length != 3) throw new IllegalArgumentException();
                Sample sample = new Sample(fields[0], canonicalInt(fields[1]), canonicalInt(fields[2]));
                if (!seen.add(sample.zone() + ":" + sample.number())) throw new IllegalArgumentException("Duplicate sample");
                samples.add(sample);
            } catch (IllegalArgumentException error) { throw new SampleFormatException(number); }
        }
        return samples;
    }
    private static void threshold(int threshold) {
        if (threshold < 0 || threshold > 5000) throw new IllegalArgumentException("Invalid threshold");
    }
    public static List<String> report(List<Sample> samples, int threshold) {
        threshold(threshold);
        Map<String, int[]> stats = new TreeMap<>();
        for (Sample sample : samples) {
            int[] values = stats.computeIfAbsent(sample.zone(), key -> new int[3]);
            values[0]++;
            values[1] = Math.max(values[1], sample.ppm());
            if (sample.ppm() > threshold) values[2]++;
        }
        List<String> lines = new ArrayList<>();
        for (Map.Entry<String, int[]> entry : stats.entrySet()) {
            int[] values = entry.getValue();
            lines.add(entry.getKey() + " count=" + values[0] + " peak=" + values[1] + " alerts=" + values[2]);
        }
        return lines;
    }
    public static void generate(Path input, Path output, int threshold) throws IOException {
        threshold(threshold);
        List<Sample> samples;
        try (BufferedReader reader = Files.newBufferedReader(input, StandardCharsets.UTF_8)) { samples = parse(reader); }
        List<String> lines = report(samples, threshold);
        try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8)) { for (String line : lines) writer.write(line + "\n"); }
    }
}

import java.io.*;
import java.nio.file.*;
public final class AirAuditCli {
    private AirAuditCli() {}
    public static int run(String[] args, PrintStream err) {
        if (args.length != 3) { err.println("Usage: AirAuditCli input output threshold"); return 2; }
        int threshold;
        try {
            threshold = Integer.parseInt(args[2]);
            if (!Integer.toString(threshold).equals(args[2]) || threshold < 0 || threshold > 5000) throw new NumberFormatException();
        } catch (NumberFormatException error) { err.println("Invalid threshold"); return 2; }
        try { AirAudit.generate(Path.of(args[0]), Path.of(args[1]), threshold); return 0; }
        catch (IOException | InvalidPathException error) { err.println(error.getMessage()); return 1; }
    }
    public static void main(String[] args) { run(args, System.err); }
}
